INSERT INTO point_sets (point_set_id, display_name, description, members, pairs)
VALUES ('heptagon-with-center', 'Heptagon With Center', 'The σ_1 projection of {0, 1, ζ_7, ζ_7^2, …, ζ_7^6} from Z[ζ_7]''s Minkowski lattice: 7 unit-circle vertices plus the origin. Produces 7 spoke unit-distance pairs (center↔vertex); no vertex-vertex pairs are unit (closest chord is 2sin(π/7) ≈ 0.868). Demonstrates the Q(ζ_7) chain end-to-end but does NOT itself achieve density exponent > 1.', NULL, NULL) ON CONFLICT (point_set_id) DO UPDATE SET display_name = EXCLUDED.display_name, description = EXCLUDED.description, members = EXCLUDED.members, pairs = EXCLUDED.pairs;

