VALUES ('zeta7-sigma1-projection', 'Q(ζ_7) σ_1 Projection', 'Project the n smallest elements of Z[ζ_7] under σ_1 into R^2. The n=8 instance is the heptagon-with-center; larger n loads additional non-unit lattice elements (sums and differences). Sawin-style higher n configurations involve restricting to elements with controlled multi-σ norms — not loaded here.', 'q-zeta-7', 'lat-q-zeta-7', NULL, NULL) ON CONFLICT (construction_family_id) DO UPDATE SET display_name = EXCLUDED.display_name, description_of_nth_member = EXCLUDED.description_of_nth_member, source_number_field = EXCLUDED.source_number_field, source_minkowski_lattice = EXCLUDED.source_minkowski_lattice, instances = EXCLUDED.instances, description = EXCLUDED.description;

