-- ----------------------------------------------------------------------------
-- AsymptoticFunctions: Table: AsymptoticFunctions. Named asymptotic functions like U(n). DefinitionText is the human-readable definition; the function's content is fully specified by the AsymptoticLowerBounds and (eventually) AsymptoticUpperBounds that reference it.
-- ----------------------------------------------------------------------------
INSERT INTO asymptotic_functions (asymptotic_function_id, display_name, definition_text, lower_bounds)
VALUES ('u-n', 'U(n)', 'U(n) = max over P ⊂ R^2 with |P|=n of e(G(P)) — the maximum number of unit-distance pairs among n planar points.', NULL) ON CONFLICT (asymptotic_function_id) DO UPDATE SET display_name = EXCLUDED.display_name, definition_text = EXCLUDED.definition_text, lower_bounds = EXCLUDED.lower_bounds;

-- ----------------------------------------------------------------------------
-- AsymptoticLowerBounds: Table: AsymptoticLowerBounds. A claim of the form 'AsymptoticFunction(n) ≥ Coefficient · n^Exponent for sufficiently large n'. Exponent is raw. IsSuperlinear, WitnessConsistent, and ExceedsTrivialLinearBound are all first-class calculated checks. WitnessConsistent compares the claimed exponent against MaxObservedDensityExponentEstimate from the supporting GrowthSequence — a finite-sample sanity check that doesn't replace the proof but does flag inconsistency.
-- ----------------------------------------------------------------------------
INSERT INTO asymptotic_lower_bounds (asymptotic_lower_bound_id, display_name, asymptotic_function, growth_sequence, exponent, coefficient, statement_text, source_citation, is_explicit, valid_from, valid_to, tx_from, tx_to, is_currently_valid, proof_pathway)
VALUES ('erdos-sqrt-bound', 'Erdős sqrt(log n) bound', 'u-n', 'sqrt-lat-growth', 1, 1, 'U(n) ≥ n^{1+c/log log n} (Erdős 1946). Proven via integer-grid construction: take the √n × √n grid Z² ∩ [0,√n]², scale so a frequent distance equals 1, then count: by Landau''s theorem on sums of two squares, certain integers k have r₂(k) representations growing like (log k)^{log 2 - 1}, and these representations yield multi-pair unit distances after scaling.', 'Erdős, 1946', FALSE, '1946-01-01', NULL, '2026-05-27', NULL, TRUE, 'combinatorial-pigeonhole') ON CONFLICT (asymptotic_lower_bound_id) DO UPDATE SET display_name = EXCLUDED.display_name, asymptotic_function = EXCLUDED.asymptotic_function, growth_sequence = EXCLUDED.growth_sequence, exponent = EXCLUDED.exponent, coefficient = EXCLUDED.coefficient, statement_text = EXCLUDED.statement_text, source_citation = EXCLUDED.source_citation, is_explicit = EXCLUDED.is_explicit, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, proof_pathway = EXCLUDED.proof_pathway;

INSERT INTO asymptotic_lower_bounds (asymptotic_lower_bound_id, display_name, asymptotic_function, growth_sequence, exponent, coefficient, statement_text, source_citation, is_explicit, valid_from, valid_to, tx_from, tx_to, is_currently_valid, proof_pathway)
VALUES ('sawin-n1014', 'Sawin n^1.014 bound (companion to OpenAI 2026)', 'u-n', 'zeta7-sigma1-growth', 1.014, 1, 'U(n) > n^{1.014} for arbitrarily large n. Sawin''s explicit refinement (2026-05-20) of OpenAI''s autonomous reasoning-model discovery (announced same day). Construction uses a cyclotomic field K = Q(ζ_p) for chosen prime p satisfying the Golod–Shafarevich criterion, projects O_K''s Minkowski lattice into R² via the first complex embedding σ_1, and counts unit-length differences among short vectors. The infinite class field tower from G–S provides the small-norm-prime density that makes the construction superlinear.', 'Sawin (2026), arXiv:2605.20579', TRUE, '2026-05-20', NULL, '2026-05-27', NULL, TRUE, 'algebraic-tower') ON CONFLICT (asymptotic_lower_bound_id) DO UPDATE SET display_name = EXCLUDED.display_name, asymptotic_function = EXCLUDED.asymptotic_function, growth_sequence = EXCLUDED.growth_sequence, exponent = EXCLUDED.exponent, coefficient = EXCLUDED.coefficient, statement_text = EXCLUDED.statement_text, source_citation = EXCLUDED.source_citation, is_explicit = EXCLUDED.is_explicit, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, proof_pathway = EXCLUDED.proof_pathway;

INSERT INTO asymptotic_lower_bounds (asymptotic_lower_bound_id, display_name, asymptotic_function, growth_sequence, exponent, coefficient, statement_text, source_citation, is_explicit, valid_from, valid_to, tx_from, tx_to, is_currently_valid, proof_pathway)
VALUES ('zeta7-witness-bound', 'Q(ζ_7) σ_1 finite witness (under-claim)', 'u-n', 'zeta7-sigma1-growth', 0.9, 1, 'U(n) ≥ n^{0.9} witnessed by the heptagon-with-center configuration (n=8, e=7 ⇒ exponent ≈ 0.937). A deliberately under-claimed exponent so WitnessConsistent resolves TRUE on the loaded instance.', 'computed from loaded data, no external citation', TRUE, '2026-05-27', NULL, '2026-05-27', NULL, TRUE, 'witness-only') ON CONFLICT (asymptotic_lower_bound_id) DO UPDATE SET display_name = EXCLUDED.display_name, asymptotic_function = EXCLUDED.asymptotic_function, growth_sequence = EXCLUDED.growth_sequence, exponent = EXCLUDED.exponent, coefficient = EXCLUDED.coefficient, statement_text = EXCLUDED.statement_text, source_citation = EXCLUDED.source_citation, is_explicit = EXCLUDED.is_explicit, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, proof_pathway = EXCLUDED.proof_pathway;

INSERT INTO asymptotic_lower_bounds (asymptotic_lower_bound_id, display_name, asymptotic_function, growth_sequence, exponent, coefficient, statement_text, source_citation, is_explicit, valid_from, valid_to, tx_from, tx_to, is_currently_valid, proof_pathway)
VALUES ('hypothetical-retracted-overclaim', 'Hypothetical Retracted Overclaim', 'u-n', NULL, 1.5, 1, 'Hypothetical: U(n) > n^{1.5} — a stylized overclaim that was once asserted and later retracted. Coverage row demonstrating valid-time retraction.', 'fictitious-preprint, retracted', TRUE, '2025-06-15', '2025-08-01', '2026-05-27', NULL, FALSE, 'other') ON CONFLICT (asymptotic_lower_bound_id) DO UPDATE SET display_name = EXCLUDED.display_name, asymptotic_function = EXCLUDED.asymptotic_function, growth_sequence = EXCLUDED.growth_sequence, exponent = EXCLUDED.exponent, coefficient = EXCLUDED.coefficient, statement_text = EXCLUDED.statement_text, source_citation = EXCLUDED.source_citation, is_explicit = EXCLUDED.is_explicit, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, proof_pathway = EXCLUDED.proof_pathway;

INSERT INTO asymptotic_lower_bounds (asymptotic_lower_bound_id, display_name, asymptotic_function, growth_sequence, exponent, coefficient, statement_text, source_citation, is_explicit, valid_from, valid_to, tx_from, tx_to, is_currently_valid, proof_pathway)
VALUES ('pending-bound-unevaluated', 'Pending Bound (Awaiting Curation)', 'u-n', NULL, 1.05, 1, 'Coverage row: a bound entered into the rulebook but not yet evaluated for current validity. IsCurrentlyValid=null.', 'pending review', TRUE, '2026-05-20', NULL, '2026-05-27', NULL, NULL, 'other') ON CONFLICT (asymptotic_lower_bound_id) DO UPDATE SET display_name = EXCLUDED.display_name, asymptotic_function = EXCLUDED.asymptotic_function, growth_sequence = EXCLUDED.growth_sequence, exponent = EXCLUDED.exponent, coefficient = EXCLUDED.coefficient, statement_text = EXCLUDED.statement_text, source_citation = EXCLUDED.source_citation, is_explicit = EXCLUDED.is_explicit, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, proof_pathway = EXCLUDED.proof_pathway;

-- ----------------------------------------------------------------------------
-- Theorems: Table: Theorems. Fixed-point anchors. A theorem refers to an AsymptoticFunction and (when anchoring a bound) a specific AsymptoticLowerBound. AnchorMatchesBoundExponent is a calculated check that the anchor's named exponent equals the referenced bound's exponent — the kind of paperwork mistake that should be caught at read-time, not in review.
-- ----------------------------------------------------------------------------
INSERT INTO theorems (theorem_id, display_name, statement_text, is_anchor, is_proven, proof_citation, asymptotic_function, anchored_lower_bound, claimed_exponent, valid_from, valid_to, tx_from, tx_to, is_currently_valid)
VALUES ('thm-superlinear-unit-distance', 'Superlinear Unit-Distance Theorem (autonomous-AI proof, 2026)', 'U(n) > n^{1.014} for arbitrarily large n. First open problem central to a subfield of mathematics solved autonomously by AI — OpenAI''s internal reasoning model produced the proof (inexplicit superlinear exponent) on 2026-05-20; Sawin''s companion paper made the exponent explicit at 1.014 the same day. The model was general-purpose: not domain-trained, not scaffolded for proof search, not targeted at the unit-distance problem. Disproves Erdős 1946''s polynomial-improvement conjecture (the long-held belief that square-grid constructions were optimal).', TRUE, TRUE, 'OpenAI (2026-05-20) autonomous announcement + Sawin (2026), arXiv:2605.20579', 'u-n', 'sawin-n1014', 1.014, '2026-05-20', NULL, '2026-05-27', NULL, TRUE) ON CONFLICT (theorem_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, is_anchor = EXCLUDED.is_anchor, is_proven = EXCLUDED.is_proven, proof_citation = EXCLUDED.proof_citation, asymptotic_function = EXCLUDED.asymptotic_function, anchored_lower_bound = EXCLUDED.anchored_lower_bound, claimed_exponent = EXCLUDED.claimed_exponent, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid;

