VALUES ('thm-erdos-unit-distance-baseline', 'Erdős Unit-Distance Lower Bound', 'U(n) ≥ n^{1+c/log log n} (Erdős 1946).', TRUE, TRUE, 'Erdős, 1946', 'u-n', 'erdos-sqrt-bound', 1, '1946-01-01', NULL, '2026-05-27', NULL, TRUE) ON CONFLICT (theorem_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, is_anchor = EXCLUDED.is_anchor, is_proven = EXCLUDED.is_proven, proof_citation = EXCLUDED.proof_citation, asymptotic_function = EXCLUDED.asymptotic_function, anchored_lower_bound = EXCLUDED.anchored_lower_bound, claimed_exponent = EXCLUDED.claimed_exponent, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid;

