VALUES ('thm-szemeredi-trotter', 'Szemerédi–Trotter Theorem', 'The number of point-line incidences among n points and m lines in R^2 is O((nm)^{2/3} + n + m).', TRUE, TRUE, 'Szemerédi–Trotter, 1983', 'u-n', NULL, NULL, '1983-01-01', NULL, '2026-05-27', NULL, TRUE) ON CONFLICT (theorem_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, is_anchor = EXCLUDED.is_anchor, is_proven = EXCLUDED.is_proven, proof_citation = EXCLUDED.proof_citation, asymptotic_function = EXCLUDED.asymptotic_function, anchored_lower_bound = EXCLUDED.anchored_lower_bound, claimed_exponent = EXCLUDED.claimed_exponent, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid;

