VALUES ('proj-q-zeta-7-sigma1', 'σ1 Projection of Lat Q-zeta-7', 'lat-q-zeta-7', 'euclidean-plane-r2', 'first-two-coords', 1, 0, FALSE, NULL, NULL, 'Pick out the first complex embedding σ_1: ζ_7 ↦ e^(2πi/7) and read off (Re, Im) ∈ R^2. NOT isometric (the R^2 image is a 2D shadow of a 6D lattice); whether it preserves unit distance depends on which lattice points get sampled — captured row-by-row in ProjectedShortVectors.') ON CONFLICT (planar_projection_id) DO UPDATE SET display_name = EXCLUDED.display_name, source_lattice = EXCLUDED.source_lattice, target_context = EXCLUDED.target_context, projection_kind = EXCLUDED.projection_kind, scaling_factor = EXCLUDED.scaling_factor, rotation_degrees = EXCLUDED.rotation_degrees, is_isometric = EXCLUDED.is_isometric, preserves_unit_distance = EXCLUDED.preserves_unit_distance, projected_short_vectors = EXCLUDED.projected_short_vectors, description = EXCLUDED.description;

