VALUES ('proj-q-zeta-7-sigma1-scaled', 'Scaled σ1 Projection of Lat Q-zeta-7', 'lat-q-zeta-7', 'euclidean-plane-r2', 'rotation-scale', 0.5773502691896258, 0, FALSE, NULL, NULL, 'σ1 followed by scaling by 1/sqrt(3) so that the powers of ζ_7 (which have squared L2-norm 3 in R^6) land near the unit circle in R^2.') ON CONFLICT (planar_projection_id) DO UPDATE SET display_name = EXCLUDED.display_name, source_lattice = EXCLUDED.source_lattice, target_context = EXCLUDED.target_context, projection_kind = EXCLUDED.projection_kind, scaling_factor = EXCLUDED.scaling_factor, rotation_degrees = EXCLUDED.rotation_degrees, is_isometric = EXCLUDED.is_isometric, preserves_unit_distance = EXCLUDED.preserves_unit_distance, projected_short_vectors = EXCLUDED.projected_short_vectors, description = EXCLUDED.description;

