-- ----------------------------------------------------------------------------
-- GolodShafarevichCriteria: Table: GolodShafarevichCriteria. The Golod–Shafarevich tower inequality, evaluated per number field. r > d^2/4 (d = minimal-generator count, r = relation count) implies an infinite class field tower — the algebraic hook used by unit-distance constructions to get many small-norm primes.
-- ----------------------------------------------------------------------------
INSERT INTO golod_shafarevich_criteria (golod_shafarevich_criterion_id, number_field, minimal_generator_count_d, relation_count_r, passes_criterion, source_reference, description)
