INSERT INTO source_references (source_reference_id, short_label, full_citation, url, year, is_arxiv, is_published, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('src-sawin-2026', 'Sawin 2026', 'Sawin, W. (2026). ''An explicit lower bound for the unit distance problem.'' arXiv:2605.20579 — companion paper to OpenAI''s May 20, 2026 autonomous-AI announcement; makes the OpenAI proof''s inexplicit exponent explicit at n^{1.014} using cyclotomic fields + Golod–Shafarevich tower + Minkowski lattice projection.', 'https://arxiv.org/abs/2605.20579', 2026, TRUE, FALSE, '2026-05-20', NULL, '2026-05-28', NULL, TRUE, NULL) ON CONFLICT (source_reference_id) DO UPDATE SET short_label = EXCLUDED.short_label, full_citation = EXCLUDED.full_citation, url = EXCLUDED.url, year = EXCLUDED.year, is_arxiv = EXCLUDED.is_arxiv, is_published = EXCLUDED.is_published, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO source_references (source_reference_id, short_label, full_citation, url, year, is_arxiv, is_published, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('src-openai-2026', 'OpenAI 2026-05-20', 'OpenAI (2026-05-20). ''An OpenAI model has disproved a central conjecture in discrete geometry.'' Official announcement at openai.com/index/model-disproves-discrete-geometry-conjecture/. First fully autonomous proof of a central open problem in mathematics: U(n) grows superlinearly with exponent > 1 (inexplicit), refuting the long-held belief that square-grid constructions are optimal. Produced by a general-purpose internal reasoning model — not domain-trained, not scaffolded for proof search, not targeted at the unit-distance problem.', 'https://openai.com/index/model-disproves-discrete-geometry-conjecture/', 2026, FALSE, TRUE, '2026-05-20', NULL, '2026-05-28', NULL, TRUE, 'The primary discovery announcement. Sawin''s companion paper (src-sawin-2026) makes the exponent explicit; this announcement is the first-mover record.') ON CONFLICT (source_reference_id) DO UPDATE SET short_label = EXCLUDED.short_label, full_citation = EXCLUDED.full_citation, url = EXCLUDED.url, year = EXCLUDED.year, is_arxiv = EXCLUDED.is_arxiv, is_published = EXCLUDED.is_published, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

