VALUES ('lemma-short-vector-counting', 'Short-vector counting for GS fields', 'src-sawin-2026', 'For number fields satisfying Golod–Shafarevich with controlled discriminant growth, the count of short vectors of squared norm at most R in the Minkowski lattice is at least c·R^{1+δ} for some explicit δ>0.', 'ShortVectors', NULL, TRUE, TRUE, '2026-05-20', NULL, '2026-05-27', NULL, TRUE, NULL) ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

