VALUES ('lemma-density-margin', 'Edge density margin over linear', 'src-sawin-2026', 'When the lattice is projected via the canonical map, the resulting point set has edge count exceeding n^{1.014} for arbitrarily large n.', 'GrowthSequences', 'sqrt-lat-growth', TRUE, TRUE, '2026-05-20', NULL, '2026-05-27', NULL, TRUE, NULL) ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-anchor-explicit-bound', 'Explicit n^1.014 anchor', 'src-sawin-2026', 'There exists an explicit construction family (anchored on Q(ζ_p) with appropriate p) realizing the n^{1.014} lower bound.', 'AsymptoticLowerBounds', 'sawin-n1014', TRUE, TRUE, '2026-05-20', NULL, '2026-05-27', NULL, TRUE, NULL) ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-spencer-auxiliary', 'Spencer 1984 auxiliary count', 'src-spencer-st-1984', 'Auxiliary edge-count bound used in classical incidence proofs.', 'UnitDistanceGraphs', NULL, FALSE, NULL, '1984-01-01', NULL, '2026-05-27', NULL, NULL, 'Named but not extracted as data yet; coverage row for IsCurrentlyValid=null.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-future-improvement', 'Future improvement lemma slot', 'src-experimental-preprint', 'Reserved row for a forthcoming improvement.', 'AsymptoticLowerBounds', NULL, NULL, NULL, '2025-06-15', '2025-08-01', '2026-05-27', NULL, FALSE, 'Inherits retraction from src-experimental-preprint.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-erdos-context', 'Erdős 1946 main theorem', 'src-erdos-1946', 'Main theorem of Erdős 1946: U(n) ≥ c · n^{1 + c''/log log n} for some absolute constants c, c'' > 0. Proof outline: take the integer grid Z² ∩ [0, √n]² (which has n points), compute all pairwise distances-squared, observe that these are sums of two squares, then apply Landau-style multiplicative bounds on r₂(k) (the number of representations of k as a²+b²) to extract a frequent distance whose multiplicity is Ω(n / (log n)^{1 - log 2}). Scaling the grid so that frequent distance becomes 1 yields the claimed unit-distance count.', 'AsymptoticLowerBounds', 'erdos-sqrt-bound', TRUE, TRUE, '1946-01-01', NULL, '2026-05-27', NULL, TRUE, 'Updated in Loop 5 with real proof content. IsLoadBearing flipped from false to true; this IS what supports the Erdős bound.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-erdos-grid-construction', 'Integer-grid pigeonhole construction', 'src-erdos-1946', 'Let G_n = Z² ∩ [0, √n]² be the √n × √n integer-grid point set; |G_n| ≈ n. For any pair (p, q) ∈ G_n × G_n, |p - q|² ∈ Z. The multiset of pairwise squared distances is concentrated: the integer k = a² + b² appears Θ(n · r₂(k)/k) times among pairs at squared-distance k (where r₂ counts representations). For k = m² · ∏ p_i with p_i ≡ 1 (mod 4), r₂(k) grows; choosing k with r₂(k) = Ω((log n)^{log 2}) gives a single squared-distance achieved Ω(n^{1+c/loglogn}) times.', 'AsymptoticLowerBounds', 'erdos-sqrt-bound', TRUE, TRUE, '1946-01-01', NULL, '2026-05-28', NULL, TRUE, 'NEW in Loop 5. The ''grid → distance histogram'' step of Erdős''s proof. The integer-distance restriction is what makes pigeonhole work — distances on a real-coordinate point set don''t concentrate, integer-grid distances do.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-erdos-divisor-function', 'Sum-of-two-squares representation count r₂(k)', 'src-erdos-1946', 'Number-theoretic fact (Landau, Hardy–Wright): the representation function r₂(k) = #{(a,b) ∈ Z² : a²+b² = k} is multiplicative; for k = 2^a · ∏ p_i^{α_i} · ∏ q_j^{β_j} with p_i ≡ 1 (mod 4) and q_j ≡ 3 (mod 4), r₂(k) = 4 · ∏(α_i+1) if all β_j even, else 0. For k = product of t primes ≡ 1 (mod 4), r₂(k) = 4 · 2^t. Choosing k with t ~ log log n gives r₂(k) ~ (log n)^{log 2}, the multiplicity needed for Erdős''s bound.', 'Lemmas', 'lemma-erdos-grid-construction', TRUE, TRUE, '1946-01-01', NULL, '2026-05-28', NULL, TRUE, 'NEW in Loop 5. The number-theoretic supporting lemma — Erdős''s bound rides on this multiplicative structure of r₂(k). Cited in 1946 to Landau; FeedsObject is the grid-construction lemma above (lemma chain: divisor-function → grid-construction → main-theorem).') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-spencer-st-crossing-inequality', 'Crossing number inequality (ACNS 1982)', 'src-spencer-st-1984', 'Ajtai–Chvátal–Newborn–Szemerédi 1982: any drawing of a graph G with n vertices and m ≥ 4n edges in the plane has at least c · m³/n² crossings (for some absolute constant c > 0). The Spencer–Szemerédi–Trotter unit-distance upper bound U(n) = O(n^{4/3}) follows from applying this to the unit-distance graph drawn with arcs.', 'Theorems', 'thm-spencer-szemeredi-trotter', TRUE, TRUE, '1982-01-01', NULL, '2026-05-28', NULL, TRUE, 'NEW in Loop 5. The crossing-number-inequality lemma that powers the upper-bound side of the sandwich on U(n). Real content from training, not placeholder.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO lemmas (lemma_id, label, source_reference, statement_text, feeds_object_table, feeds_object_id, is_loaded, is_load_bearing, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('lemma-historical-background-context', 'Historical context (background, not load-bearing)', 'src-erdos-1946', 'Background-only: Erdős conjectured in conversation that U(n) might be expressible as a polylogarithmic factor times n. This is context, not a step in any proof. Coverage row for IsLoadBearing=FALSE.', 'Conjectures', 'conj-erdos-polynomial-improvement', TRUE, FALSE, '1946-01-01', NULL, '2026-05-28', NULL, TRUE, 'Coverage row for IsLoadBearing=FALSE — historical context that is loaded but doesn''t underwrite any specific bound.') ON CONFLICT (lemma_id) DO UPDATE SET label = EXCLUDED.label, source_reference = EXCLUDED.source_reference, statement_text = EXCLUDED.statement_text, feeds_object_table = EXCLUDED.feeds_object_table, feeds_object_id = EXCLUDED.feeds_object_id, is_loaded = EXCLUDED.is_loaded, is_load_bearing = EXCLUDED.is_load_bearing, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

