-- ----------------------------------------------------------------------------
-- Conjectures: Table: Conjectures. Open and resolved conjectures about an AsymptoticFunction — distinct from Theorems (which are proved) because a conjecture is named, has a target exponent, and carries a resolution status that may change over time. Erdős's polynomial-improvement conjecture sits here; Sawin's resolved-as-proved conjecture-then-theorem is cross-referenced.
-- ----------------------------------------------------------------------------
INSERT INTO conjectures (conjecture_id, display_name, statement_text, target_function, conjectured_exponent, is_conjectural_upper_bound, is_conjectural_lower_bound, proposed_by, is_resolved, resolved_as, resolution_citation, related_theorem, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('conj-erdos-polynomial-improvement', 'Erdős Polynomial Improvement Conjecture', 'U(n) = O(n^{1+ε}) for every ε > 0 — i.e., the unit-distance count is no more than slightly-superlinear.', 'u-n', 1, TRUE, FALSE, 'src-erdos-1946', FALSE, NULL, NULL, NULL, '1946-01-01', NULL, '2026-05-27', NULL, TRUE, 'The most famous open question about U(n). Still open as of every loaded source.') ON CONFLICT (conjecture_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, target_function = EXCLUDED.target_function, conjectured_exponent = EXCLUDED.conjectured_exponent, is_conjectural_upper_bound = EXCLUDED.is_conjectural_upper_bound, is_conjectural_lower_bound = EXCLUDED.is_conjectural_lower_bound, proposed_by = EXCLUDED.proposed_by, is_resolved = EXCLUDED.is_resolved, resolved_as = EXCLUDED.resolved_as, resolution_citation = EXCLUDED.resolution_citation, related_theorem = EXCLUDED.related_theorem, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

