VALUES ('conj-erdos-43-tightness', 'Erdős 4/3 Tightness Conjecture', 'U(n) ≤ c · n^{4/3} — that the Spencer–Szemerédi–Trotter upper bound is tight up to constants.', 'u-n', 1.3333333333, TRUE, FALSE, 'src-erdos-1946', FALSE, NULL, NULL, NULL, '1946-01-01', NULL, '2026-05-27', NULL, TRUE, 'Folklore-strength: would mean ST is the right shape.') ON CONFLICT (conjecture_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, target_function = EXCLUDED.target_function, conjectured_exponent = EXCLUDED.conjectured_exponent, is_conjectural_upper_bound = EXCLUDED.is_conjectural_upper_bound, is_conjectural_lower_bound = EXCLUDED.is_conjectural_lower_bound, proposed_by = EXCLUDED.proposed_by, is_resolved = EXCLUDED.is_resolved, resolved_as = EXCLUDED.resolved_as, resolution_citation = EXCLUDED.resolution_citation, related_theorem = EXCLUDED.related_theorem, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

INSERT INTO conjectures (conjecture_id, display_name, statement_text, target_function, conjectured_exponent, is_conjectural_upper_bound, is_conjectural_lower_bound, proposed_by, is_resolved, resolved_as, resolution_citation, related_theorem, valid_from, valid_to, tx_from, tx_to, is_currently_valid, description)
VALUES ('conj-sawin-resolved', 'Polynomial superlinear improvement conjecture (resolved by OpenAI + Sawin 2026)', 'Pre-2026 conjecture: there exists an explicit construction giving U(n) > n^c for some c > 1, for arbitrarily large n. Resolved 2026-05-20 by OpenAI''s autonomous reasoning model (inexplicit c > 1) + Sawin''s same-day explicit companion paper (c = 1.014 via cyclotomic + Golod–Shafarevich).', 'u-n', 1.014, FALSE, TRUE, 'src-erdos-1946', TRUE, 'proved', 'src-openai-2026', 'thm-superlinear-unit-distance', '1946-01-01', '2026-05-20', '2026-05-27', NULL, FALSE, 'Open for 80 years; resolved 2026-05-20. ValidTo marks the resolution moment. The proposition itself is now TRUE as a theorem (RelatedTheorem). The pre-resolution proposer is Erdős (1946 framing); the resolver is OpenAI''s autonomous model.') ON CONFLICT (conjecture_id) DO UPDATE SET display_name = EXCLUDED.display_name, statement_text = EXCLUDED.statement_text, target_function = EXCLUDED.target_function, conjectured_exponent = EXCLUDED.conjectured_exponent, is_conjectural_upper_bound = EXCLUDED.is_conjectural_upper_bound, is_conjectural_lower_bound = EXCLUDED.is_conjectural_lower_bound, proposed_by = EXCLUDED.proposed_by, is_resolved = EXCLUDED.is_resolved, resolved_as = EXCLUDED.resolved_as, resolution_citation = EXCLUDED.resolution_citation, related_theorem = EXCLUDED.related_theorem, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

