VALUES ('ak-coverage-unmatched', 'Conjectures', 'conj-future-improvement-slot', 'IsResolved', 'boolean', NULL, NULL, FALSE, NULL, 'info', FALSE, '2026-05-20', '2026-05-25', '2026-05-27', NULL, FALSE, 'Coverage row: this expected-value pin was retired (superseded by a later one); IsCurrentlyValid=false.') ON CONFLICT (answer_key_id) DO UPDATE SET target_table = EXCLUDED.target_table, target_row_id = EXCLUDED.target_row_id, target_field = EXCLUDED.target_field, data_type = EXCLUDED.data_type, expected_string = EXCLUDED.expected_string, expected_number = EXCLUDED.expected_number, expected_boolean = EXCLUDED.expected_boolean, tolerance = EXCLUDED.tolerance, gate_level = EXCLUDED.gate_level, is_currently_matched = EXCLUDED.is_currently_matched, valid_from = EXCLUDED.valid_from, valid_to = EXCLUDED.valid_to, tx_from = EXCLUDED.tx_from, tx_to = EXCLUDED.tx_to, is_currently_valid = EXCLUDED.is_currently_valid, description = EXCLUDED.description;

-- ----------------------------------------------------------------------------
-- TemporalSnapshots: Table: TemporalSnapshots. Named moments in the historical progression of the unit-distance problem. Each row pins a calendar date with a label so chronology becomes a first-class entity. Aggregations against bitemporal columns elsewhere in the rulebook can reference these moments by name instead of by raw ISO string.
-- ----------------------------------------------------------------------------
INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-erdos-1946', 'Erdős 1946 publication', '1946-01-01', 'Erdős''s original ''On sets of distances of n points'' establishes U(n) ≥ n^{1+c/loglogn}. The starting line of the lower-bound program.', TRUE, 'src-erdos-1946') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-st-1983', 'Szemerédi–Trotter 1983', '1983-01-01', 'Szemerédi–Trotter incidence bound published. Sets up the upper-bound side.', TRUE, 'src-szemeredi-trotter-1983') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-spencer-st-1984', 'Spencer–Szemerédi–Trotter 1984', '1984-01-01', 'Specialization of ST to unit distances: U(n) = O(n^{4/3}). The ceiling.', TRUE, 'src-spencer-st-1984') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-openai-2026-may-20', 'OpenAI autonomous-AI announcement', '2026-05-20', 'OpenAI''s reasoning model autonomously proved U(n) grows superlinearly (inexplicit exponent > 1), disproving Erdős''s polynomial-improvement conjecture and showing the square-grid was not optimal. First autonomous AI proof of a central open mathematics problem.', TRUE, 'src-openai-2026') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-sawin-2026', 'Sawin 2026 companion paper (explicit n^1.014)', '2026-05-20', 'Sawin''s companion paper, posted the same day as the OpenAI announcement, makes the exponent explicit at 1.014 using cyclotomic fields, Golod–Shafarevich tower argument, and Minkowski lattice projection. The structural chain Q(ζ_p) → O_K → Minkowski lattice → short-vector counting → planar projection is what the rulebook''s algebraic-tower pathway models.', TRUE, 'src-sawin-2026') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-mid-overclaim-2025', 'Mid-overclaim 2025-07', '2025-07-01', 'A moment during the hypothetical-retracted-overclaim''s brief validity window (2025-06-15 → 2025-08-01). At this instant the rulebook briefly held an exponent-1.5 claim that was retracted shortly after — useful for proving the bitemporal layer captures transient overclaims.', TRUE, 'src-experimental-preprint') ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-now', 'Current moment', '2026-05-28', 'The ''now'' anchor — present-day state of the rulebook.', FALSE, NULL) ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

INSERT INTO temporal_snapshots (temporal_snapshot_id, label, snapshot_date, description, is_historical, anchoring_source_reference)
VALUES ('snap-future-projected', 'Future improvement (projected)', '2030-01-01', 'Placeholder for the next plausible improvement — for forward-looking ''will the chain still close in 2030'' queries.', NULL, NULL) ON CONFLICT (temporal_snapshot_id) DO UPDATE SET label = EXCLUDED.label, snapshot_date = EXCLUDED.snapshot_date, description = EXCLUDED.description, is_historical = EXCLUDED.is_historical, anchoring_source_reference = EXCLUDED.anchoring_source_reference;

-- ----------------------------------------------------------------------------
